using System.Windows;
using ParadoxModTool.Localization;

namespace ParadoxModTool.App;

/// <summary>
/// Anleitung zu Generator-Paketen und zum Paket-Editor (Spec Teil 5a, Abschnitt 5) mit Inhaltsverzeichnis und Suche. Durchgehendes Beispiel ist das erfundene
/// Paket "Stadtwappen"; Sonderfälle zeigen Ausschnitte aus IV2. Überschriften mit Schlüssel sind Sprungziele für F1 im Paket-Editor.
/// </summary>
public sealed class GeneratorPackageHelpWindow : GuideWindow
{
    private static GeneratorPackageHelpWindow? _open;

    private GeneratorPackageHelpWindow()
        : base(T("generatorhelp.title", "Anleitung: Generator-Pakete"), Blocks, withNavigation: true)
    {
    }

    /// <summary>Die Blöcke in der geladenen Oberflächensprache; bei jedem Öffnen neu gebaut, damit die Sprache stimmt.</summary>
    private static GuideBlock[] Blocks => new[]
    {
        new GuideBlock(GuideBlockKind.Title, T("generatorhelp.title", "Anleitung: Generator-Pakete")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.intro.heading", "Wozu Generator-Pakete?"), "generatorhelp.intro"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.intro.what", "Ein Generator-Paket erzeugt aus einem Formular viele Mod-Dateien auf einmal: eigene Dateien, Lokalisierung in allen Sprachen, Abschnitte in bestehenden Dateien und Bilder. Beispiel IV2: Aus Tag, Wappen und den Ideen eines Landes entstehen 18 Dateien.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.intro.how", "Das Paket beschreibt Formular und Ausgaben einmal. Danach füllst du im Fenster „Generator-Pakete“ nur noch das Formular aus, je Land oder was der Schlüssel des Pakets ist. PMT zeigt eine Vorschau und schreibt alles als einen Rückgängig-Schritt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.intro.editor", "Im Paket-Editor legst du Pakete an und bearbeitest sie mit Masken, ohne JSON zu schreiben. Durchgehendes Beispiel dieser Anleitung ist ein erfundenes Paket „Stadtwappen“:")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.intro.box", "Paket stadtwappen (EU V)\n  Kopf:      tag (Text, Pflicht, Muster ^[A-Z0-9]{3}$)\n  Ebene:     ideas (zählbar, 1 bis 5), Felder name (mehrsprachig) und modifiers\n  Ausgaben:  ownFile        in_game/common/static_modifiers/sw_{{ tag }}.txt\n             localization   main_menu/localization/{{ lang }}/sw_{{ tag }}_l_{{ lang }}.yml\n             insertSection  in_game/common/scripted_triggers/sw_setup.txt, Block sw_tags")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.steps.heading", "Ablauf"), "generatorhelp.steps"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.steps.list", "1. Paket anlegen: im Paket-Editor „Neu“, Kennung stadtwappen.\n2. Formular: Kopf-Felder und Ebenen mit ihren Feldern.\n3. Ausgaben: was in welche Datei geschrieben wird.\n4. Vorlagen: der Text jeder Ausgabe, in Scriban.\n5. „Prüfen“: lädt das Paket probeweise und prüft alle Vorlagen.\n6. „Im Generator testen“: öffnet das Generator-Fenster auf diesem Paket. Zum Testen das Ziel „Ausgabeordner“ wählen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.steps.save", "Strg+S speichert. Auch ein halb fertiges Paket lässt sich speichern; Fehler zeigt „Prüfen“. Der Fenstertitel zeigt *, solange etwas ungespeichert ist. Mitgelieferte Pakete wie IV2 (🔒) sind schreibgeschützt; „Als Kopie bearbeiten“ legt eine eigene Kopie mit neuer Kennung an.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.basics.heading", "Grunddaten und Ziele"), "generatorhelp.basics"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.basics.fields", "Die Kennung ist der Ordnername des Pakets und lässt sich nur über eine Kopie ändern. Der Name erscheint in der Paketliste, in jeder Sprache. Das Spiel bestimmt, wo das Paket liegt und wann es in der Liste erscheint. Das Schlüsselfeld ist das Kopf-Feld, dessen Wert einen Arbeitsstand benennt; bei Stadtwappen ist es tag, je Tag ein Arbeitsstand.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.basics.markerId", "Die Markierungs-Kennung steht in den Zeilen, mit denen PMT seine Abschnitte in der Mod wiederfindet (# PMT-Generator iv2/...). Leer gilt die Paket-Kennung. „Als Kopie bearbeiten“ und ein Import unter neuer Kennung tragen die Kennung des Originals ein: So ersetzt die Kopie die Abschnitte des Originals, statt sie ein zweites Mal zu schreiben. Hat eine ältere Kopie das Feld leer, trag dort die Kennung des Originals ein, z. B. iv2.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.basics.targets", "Ziele: „mod“ schreibt direkt in den Mod-Ordner. „output“ schreibt in einen gewählten Ordner und kopiert vorher jede Mod-Datei, die es ändert, dorthin. Mit „output“ testest du gefahrlos; mehrere Schlüssel sammeln sich im selben Ausgabeordner.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.form.heading", "Formular: Kopf, Ebenen und Felder"), "generatorhelp.form"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.form.levels", "Kopf-Felder fragt das Formular einmal je Arbeitsstand ab, etwa tag. Darunter steht eine Kette von Ebenen: jede Ebene hat Felder und höchstens eine Kind-Ebene. Eine zählbare Ebene hat zwischen Min und Max Elemente, die der Nutzer anlegt; die Anfangszahl gilt für neue Arbeitsstände. Eine feste Ebene hat ein Element je Zeile einer Konstanten-Tabelle.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.form.number", "Jedes Element hat eine Nummer: ohne Nummer-Basisfeld ist es sein Index ab 1, mit Nummer-Basisfeld der Wert dieses Felds der Elternebene plus der Index. So bekommt IV2 eindeutige Nummern über alle Kategorien:")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.form.box", "categories  fest, Tabelle categories (adm base 0, dip base 10, ...)\n  ideas     zählbar 0 bis 9, Nummer-Basisfeld base\n    levels  zählbar 1 bis 4\n\nIdee 2 in dip hat die Nummer 12.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.form.types", "Feldarten: Text, mehrzeiliger Text, Zahl, Ja/Nein (yes/no), Auswahl (Werte je Zeile), Bild (aus einer Asset-Bibliothek, mit „Wappen wählen“) und Modifikatoren (mehrzeilig, mit „+ Modifier“). Pflichtfeld und Muster (regulärer Ausdruck) blockieren das Erzeugen, solange sie nicht erfüllt sind. Auch eine Modifier-Zeile ohne Wert („schluessel = “) blockiert es. „Mehrsprachig“ gibt Textfeldern einen Übersetzungen-Dialog.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.form.ids", "Die Kennung eines Felds oder einer Ebene ist ihr Name in den Vorlagen: Buchstaben, Ziffern und _, nicht mit einer Ziffer am Anfang. Eine geänderte Kennung gilt, sobald du das Feld verlässt; Vorlagen, die den alten Namen nutzen, melden danach beim Prüfen einen Fehler.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.form.autoNumber", "Nummer automatisch (autoNumber): Das letzte Schlüsselfeld vom Typ Zahl im Kopf kann „Nummer automatisch“ bekommen, z. B. die Nummer einer Ideengruppe. „Neuer Stand“ trägt dort die höchste Nummer ein, die die Arbeitsstände und das Einlesen für die übrigen Schlüsselteile kennen, plus 1; man kann sie überschreiben. Vor der Vorschau prüft PMT die Hashes der Lokalisierungsschlüssel: Kollidiert ein neuer Stand mit einem Schlüssel des Spiels oder der Mod, rückt er auf die nächste Nummer ohne Kollision. Ein Schlüssel, den die Mod schon hat, wird nie umnummeriert und bekommt nur eine Warnung.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.constants.heading", "Konstanten"), "generatorhelp.constants"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.constants.text", "Konstanten sind Tabellen mit Zeilen und Spalten, die das Paket fest mitbringt. Eine feste Ebene hat je Zeile ein Element, und die Spalten lassen sich in Vorlagen wie Felder lesen, z. B. c.base. Die Spalte label darf je Sprache einen Text haben („Sprachen der Zelle“); das Formular zeigt sie als Überschrift. Umbenennen einer Tabelle passt die Ebenen an, die sie nutzen.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.languages.heading", "Mehrsprachige Texte und Sprachregeln"), "generatorhelp.languages"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.languages.texts", "Paketname, Beschriftungen und Meldungen sind entweder ein Text für alle Sprachen oder je Sprache ein Text. Das Feld zeigt die Sprache der Oberfläche; „Sprachen“ öffnet alle acht. Bleibt nur Englisch mit dem alten Text, bleibt es ein einfacher Text.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.languages.rules", "Die Sprachregeln gelten für mehrsprachige Felder und sind Vorgaben, die jeder Arbeitsstand ändern kann:\n• Englisch erweitern: Lokalisierung für alle Sprachen des Spielprofils, ohne Übersetzung mit dem englischen Text.\n• Englisch kopieren: leere Sprachen bekommen den englischen Text.\n• Englisch für fehlende: hat ein Eintrag Übersetzungen, bekommen seine fehlenden Sprachen den englischen Text.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.assets.heading", "Assets und Herkunft"), "generatorhelp.assets"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.assets.text", "Assets sind Zip-Dateien oder Ordner im Datenordner des Pakets, etwa eine Wappenbibliothek. Bildfelder wählen daraus, copyBinary-Ausgaben kopieren daraus. „Datei wählen“ kopiert eine Datei in den Ordner assets und setzt den Pfad; der Status zeigt, ob die Datei da ist.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.assets.origin", "Herkunft: „Spiel“ heißt aus den Spieldateien, solche Assets werden nie exportiert. „Mod/eigene“ heißt aus einer Mod oder selbst erstellt; sie darfst du beim Export mitgeben. Ohne Angabe gilt „Spiel“. Gib Bilder aus dem Spiel nicht weiter, auch nicht von Hand.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.outputs.heading", "Ausgabearten"), "generatorhelp.outputs"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.intro", "Jede Ausgabe hat eine Kennung, eine Art und einen Pfad. Der Pfad ist eine Scriban-Vorlage relativ zur Mod und muss in der Mod bleiben: ein Pfad mit .., einem Laufwerk oder einem führenden / ist ein Fehler. Mit „Je Element“ entsteht die Ausgabe einmal je Element einer Ebene; in der Vorlage heißt das Element item.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.ownFile", "Eigene Datei (ownFile): schreibt die ganze Datei aus der Vorlage.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.outputs.ownFileBox", "Pfad:     in_game/common/static_modifiers/sw_{{ tag }}.txt\nVorlage:  modifiers.sbn\n\nErgebnis für tag = HAM:  in_game/common/static_modifiers/sw_HAM.txt")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.localization", "Lokalisierung (localization): eine Datei je Sprache; {{ lang }} im Pfad wird zur Sprache. PMT setzt l_<sprache>: davor, wenn die Vorlage es nicht tut, und schreibt mehrsprachige Felder in der Sprache der Datei, \" als \\\" und Zeilenumbrüche als \\n.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.outputs.localizationBox", "Pfad:     main_menu/localization/{{ lang }}/sw_{{ tag }}_l_{{ lang }}.yml\nVorlage:  {{ for i in ideas -}}\n           sw_{{ tag }}_{{ i.number }}: \"{{ i.name }}\"\n          {{ end -}}\n\nErgebnis (german):  l_german:\n                     sw_HAM_1: \"Hansestolz\"")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.insertSection", "Abschnitt einfügen (insertSection): setzt den Text zwischen Markierungen in einen Block oder ans Dateiende. Ein zweiter Lauf ersetzt nur den Text zwischen den Markierungen. Fehlt die Datei, legt das Grundgerüst sie an.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.outputs.insertSectionBox", "Block:    sw_tags\nVorlage:  has_or_had_tag = {{ tag }}\n\nsw_tags = {\n\t# PMT-Generator stadtwappen/setup/HAM begin\n\thas_or_had_tag = HAM\n\t# PMT-Generator stadtwappen/setup/HAM end\n}")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.ensureLine", "Zeile sicherstellen (ensureLine): fügt eine Zeile in einen Block ein, wenn sie fehlt, z. B. has_or_had_tag = {{ tag }} in einer OR-Liste. Ohne Markierungen; eine vorhandene Zeile bleibt unberührt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.syncBlocks", "Blöcke abgleichen (syncBlocks): gleicht Blöcke der obersten Ebene ab, deren Schlüssel das Schlüsselmuster trifft (* = Namenszeichen). Fehlende kommen dazu, nicht mehr erzeugte werden nach Rückfrage entfernt, und nur die Teilschlüssel aus der Vorlage werden ersetzt. Mit „Behalten“ (IV2: game_data) bleiben diese Teilschlüssel stehen.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.outputs.syncBlocksBox", "Schlüsselmuster:  sw_modifier_{{ tag }}_*\nBehalten:         game_data\n\nsw_modifier_HAM_1 = {\n\tgame_data = { category = economic }   <- bleibt\n\ttrade_efficiency = 0.1               <- aus der Vorlage\n}")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.copyBinary", "Datei kopieren (copyBinary): kopiert eine Datei aus einem Asset, z. B. das gewählte Wappen. Die Quelle ist Asset und Eintrag, etwa coa und {{ coa }}. Ein leerer Eintrag überspringt die Ausgabe; fehlt die Bibliothek, überspringt PMT sie mit Hinweis.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.outputs.jsonEntry", "JSON-Eintrag (jsonEntry): setzt einen Eintrag in eine JSON-Datei außerhalb der Mod, z. B. in die Tag-Liste eines Hilfsskripts. Die Datei steht unter „Externe Dateien“, den Pfad wählt man im Generator-Fenster; die Ausgabe braucht keinen Pfad. „JSON-Pfad“ ist der Punkt-Pfad zum Objekt in der Datei (leer = oberstes Objekt), „Eintragsschlüssel“ der Schlüssel darin, und die Vorlage erzeugt den Wert als JSON. Ein vorhandener Schlüssel wird an Ort und Stelle ersetzt, ein neuer ans Ende gehängt; der Rest der Datei bleibt Byte für Byte gleich.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.outputs.jsonEntryBox", "Externe Datei:      tags\nJSON-Pfad:          entries\nEintragsschlüssel:  {{ tag }}\nVorlage:            { \"name\": \"{{ name }}\" }\n\nErgebnis für tag = HAM:  \"entries\": { ..., \"HAM\": { \"name\": \"Hansestolz\" } }")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.externals.heading", "Externe Dateien und Hinweis"), "generatorhelp.externals"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.externals.text", "Der Abschnitt „Externe Dateien“ nennt Dateien außerhalb der Mod, in die Ausgaben der Art jsonEntry schreiben. Jede hat eine Kennung, eine Beschriftung und einen Hinweis (Tooltip) je Sprache. Der Pfad steht nicht im Paket: Das Generator-Fenster zeigt je Datei eine Zeile mit „Datei wählen“ und merkt sich den Pfad je Paket. Ist keine Datei gewählt oder fehlt sie, überspringt PMT die Ausgabe mit einer Warnung. Beim Erzeugen kopiert PMT die alte Datei zuerst in den Ordner backups neben ihr und schreibt nicht, wenn sie sich seit der Vorschau geändert hat. „Mod prüfen“ ignoriert diese Dateien.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.externals.afterGenerate", "Hinweis nach dem Erzeugen (afterGenerate): Der Text erscheint im Generator-Fenster unter der Meldung, wenn das Erzeugen gelungen ist, z. B. als Erinnerung an ein Hilfsskript, das danach laufen muss. Bei Fehlern oder Abbruch erscheint er nicht.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.markers.heading", "Blockpfade und Markierungen"), "generatorhelp.markers"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.markers.paths", "Ein Blockpfad nennt Schlüssel mit Punkt getrennt, z. B. sw_setup.sw_tags. In .gui-Dateien geht auch ein Kopf wie types name, type name oder template name; type name wird in jedem types-Block der Ebene gesucht.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.markers.legacy", "Alt-Markierungen: Hat ein älteres Werkzeug schon Abschnitte geschrieben, nennen Alt-Anfang und Alt-Ende seine Markierungen. PMT findet und behält sie und ersetzt nur den Text dazwischen. Alt-Muster sind reguläre Ausdrücke für unmarkierte Alt-Einträge; PMT entfernt sie vor dem Einfügen und nennt die Zahl in der Vorschau. Jedes Muster braucht eine feste Grenze nach dem Schlüssel, z. B. _\\d+, damit CA nicht CAS trifft.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.markers.box", "IV2:\n  Alt-Anfang:  # === IV2Generator:{{ tag }}:START ===\n  Alt-Ende:    # === IV2Generator:{{ tag }}:END ===\n  Alt-Muster:  ^\\s*iv2_historic_idea_select_{{ tag }}_\\d+")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.templates.heading", "Vorlagen (Scriban)"), "generatorhelp.templates"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.templates.names", "Vorlagen sind Scriban-Texte im Ordner templates. Sie kennen die Kopf-Felder (tag), je Ebene eine Liste (ideas) mit den Feldern jedes Elements und dazu index, index0, first, last, number, suffix und parent, außerdem item, lang, constants, languages und language_rules. Die Liste „Verfügbare Namen“ rechts zeigt alles; ein Doppelklick fügt den Namen ein.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.templates.whitespace", "Mit -}} entfällt der Zeilenumbruch nach einem Tag; so stehen Schleifen ordentlich je Zeile:")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.templates.box", "{{ for i in ideas -}}\nsw_modifier_{{ tag }}_{{ i.number }} = {\n{{ i.modifiers }}\n}\n{{ end -}}")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.templates.functions", "functions.sbn enthält eigene Funktionen (func name ... end), die jede Vorlage nutzen kann. Vorlagentexte schreibt erst „Speichern“; Umbenennen und Löschen speichern das Paket sofort, damit Datei und Verweise zusammenpassen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.templates.errors", "Häufige Fehler:\n• Ein unbekannter Name ist ein Fehler mit Vorlage und Zeile, z. B. ein Tippfehler im Feldnamen.\n• for oder if ohne end.\n• Vergessene }} in einem Pfad oder Block.\n„Prüfen“ findet beides: Lesefehler und, mit einem Probe-Erzeugen, auch unbekannte Namen.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.messages.heading", "Warnungen und Fehler"), "generatorhelp.messages"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.messages.text", "Eine Bedingung ist ein Scriban-Ausdruck. Ist eine Warnung wahr, fragt der Generator vor dem Erzeugen nach; ist ein Fehler wahr, verweigert er das Erzeugen. Die Meldung darf je Sprache einen Text haben.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.messages.box", "Warnung:  ideas.size < 3        Weniger als 3 Ideen\nFehler:   ideas.size == 0       Keine Idee angelegt")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.read.heading", "Einlesen (Aus Mod einlesen)"), "generatorhelp.read"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.read.intro", "Mit dem Abschnitt „Einlesen“ liest der Generator einen Satz, den eine Mod schon enthält, zurück ins Formular. „Aus Mod einlesen“, „Tags aus Mod übernehmen“ und „Mod prüfen“ nutzen ihn. Die Muster sind reguläre Ausdrücke; {{ tag }} steht für den Schlüssel.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.read.steps", "Schritt für Schritt:\n• Schlüssel-Dateien: Muster auf die Pfade der Mod; die Gruppe (?<key>...) nennt den Satz.\n• Elemente: eine Datei mit einem Block je Element und ein Block-Muster mit (?<number>...). Die Nummer findet das Element wie beim Erzeugen (Basis plus Index); (?<suffix>...) wählt das Element der tieferen Ebene.\n• Je Feld der Ebene legt „Blockinhalt übernehmen“ die Zeilen des Blocks ins Feld; „Ausnahmen“ lässt Schlüssel wie game_data weg.\n• Lokalisierung, Ja/Nein-Merkmale und Bilder füllen weitere Felder.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.read.box", "Schlüssel-Dateien:  ^in_game/common/static_modifiers/sw_(?<key>[A-Z]{3})\\.txt$\nDatei:              in_game/common/static_modifiers/sw_{{ tag }}.txt\nBlock-Muster:       sw_modifier_{{ tag }}_(?<number>\\d+)\nEbene:              ideas; modifiers: Blockinhalt übernehmen, Ausnahmen game_data\nLokalisierung:      sw_{{ tag }}_(?<number>\\d+)  ->  ideas.name")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.read.suggest", "„Vorschlag“ baut ein Muster aus einem Beispiel: Mod wählen, dann eine Datei, einen Block oder einen Lokalisierungsschlüssel anklicken. PMT ersetzt den Schlüssel (z. B. HAM) durch {{ tag }} bzw. (?<key>...), die erste Zahl dahinter durch (?<number>\\d+) und ein _1 am Ende durch (?<suffix>_\\d+)?. Für Blöcke mit Stufen ein Beispiel mit Endung wählen, sonst fehlt die Gruppe suffix.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.read.probe", "„Probelauf“ liest einen Satz aus einer gewählten Mod mit den aktuellen Mustern, ohne zu speichern oder zu schreiben. Der Reiter „Treffer“ zeigt je Muster, was es findet; ein Muster ohne Treffer steht als Warnung da. „Ergebnis“ zeigt den eingelesenen Stand, „Hinweise“ die Meldungen des Einlesers, z. B. Nummern außerhalb jeder Gruppe. Alle Pfade bleiben in der Mod: Pfade mit .., Laufwerk oder führendem / überspringt der Einleser.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.shared.heading", "Gemeinsame Dateien"), "generatorhelp.shared"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.intro", "Manche Sätze haben keine eigenen Dateien, sondern stehen verstreut in Dateien, die sie mit allen anderen teilen, wie die Ideengruppen von Idea Variation 2: eine Gruppe steckt in rund 30 Dateien, als Blöcke, GUI-Typen, Listeneinträge, unbenannte if-Blöcke und Lokalisierungszeilen. Dafür gibt es drei Bausteine.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.match", "„Abgleich nach Treffer“ (syncMatching): Die Einträge eines Blocks (oder der Datei) sind Einheiten: Anweisungen, GUI-Kopfzeilen mit Inhalt, Listenwerte, unbenannte Blöcke und eigene Kommentarzeilen. Jede Einheit, in deren Text das Treffer-Muster trifft, gehört zum Satz; PMT ersetzt sie an Ort und Stelle durch den Text der Vorlage, ohne Markierungen. Ohne Treffer kommt der Text ans Blockende. Grenzen gehören ins Muster, damit adm_1 nicht adm_18 trifft. Die Vorlage schreibt die Einrückung, die die Datei an dieser Stelle hat.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.insertAfter", "„Einfügen nach“ (insertAfter, auch bei Lokalisierung mit Schlüssel-Muster): Ohne Angabe kommt ein neuer Satz ans Blockende. Mit diesem Muster (regulärer Ausdruck mit Scriban, geprüft gegen den Text jeder Einheit, bei Lokalisierung gegen den Schlüssel) kommt er direkt hinter die letzte Einheit, die es trifft, z. B. hinter die vorige Gruppe, damit die Reihenfolge in der Datei stimmt. Das gilt nur, solange noch keine Einheit des Satzes steht; vorhandene behalten ihren Platz. Trifft das Muster nichts, gilt die Standardstelle.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.ifLimit", "„Bedingung (if/limit)“ (ifLimit, nur bei Abgleich nach Treffer): Manche Dateien gruppieren Einträge in if-Blöcken mit einer limit-Bedingung. Die Vorlage der Bedingung (Scriban, eine Zeile je Bedingung) legt fest, wohin der Text gehört: leer gerendert auf die oberste Ebene, sonst in den if-Block mit genau dieser Bedingung, den PMT anlegt, wenn es ihn noch nicht gibt. Ändert sich die Bedingung, zieht der Satz um, und ein dadurch leerer if-Block verschwindet. Die Vorlage rückt dann eine Ebene tiefer ein.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.localization", "Lokalisierung mit „Schlüssel-Muster (gemeinsame Datei)“: PMT ersetzt nur die Zeilen, deren Schlüssel passt, und lässt alle anderen Zeilen der Datei stehen. Ohne Muster schreibt eine Lokalisierung wie bisher die ganze Datei, das löscht in einer gemeinsamen Datei alle anderen Sätze.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.keys", "Schlüssel aus mehreren Feldern: Unter „Grunddaten“ können mehrere Schlüsselfelder gewählt werden, z. B. Kategorie (Auswahl) und Nummer; der Schlüssel heißt dann adm_18. Beim Einlesen kommen die Schlüssel aus Blöcken in Dateien, Kopf-Felder wie der Titel aus der Lokalisierung, und „Werte sammeln“ liest z. B. alle Religionen einer Gruppe.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.shared.check", "„Prüfung“ (check) schreibt nichts: Jede Zeile der Vorlage ist „Muster => Argument“. Nach allen anderen Ausgaben sucht PMT jedes Muster im geplanten Text der Datei; trifft es nicht, zeigt die Vorschau die Meldung als Warnung, mit {{ arg }} für das Argument. So lässt sich z. B. melden, dass eine Partnergruppe diese Gruppe noch nicht ausschließt und neu erzeugt werden muss. Liegen Texte in einer zweiten gemeinsamen Lokalisierungsdatei, nennt beim Einlesen jeder Eintrag seine eigene „Ausgabe“.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.shared.box", "Ausgabe:        Abgleich nach Treffer, Block „types iv2_ideagroups_adm_all“\nTreffer-Muster: type iv2_ig_{{ category }}_{{ group }}(?![0-9])\nLokalisierung:  Schlüssel-Muster ^iv2_ga_ideagroup_{{ category }}_{{ group }}(_|$)\nEinlesen:       Schlüssel aus Blöcken, ideagroup_modifier_(?<category>adm|dip)_(?<group>\\d+)_1")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.lookups.heading", "Nachschlagen (Aus Datenbank)"), "generatorhelp.lookups"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.lookups.intro", "Nachschlage-Quellen liefern Einträge für „Aus Datenbank“: Schlüssel, Name, Beschreibung, Tag und Nation. Ein Text-Feld nennt unter „Aus Datenbank nachschlagen“ seine Quellen und die Felder, die Name und Beschreibung bekommen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.lookups.game", "„Aus dem Spiel“ liest jede .txt-Datei im Ordner des Spielinhalts. Tiefe 1 nimmt die obersten Blöcke, Tiefe 2 auch ihre Unterblöcke. „Nur Blöcke mit Namen“ lässt Blöcke ohne Lokalisierungstext weg. Name und Beschreibung kommen aus der Lokalisierung des Spiels (<key> und <key>_desc), auch in den anderen Sprachen des Arbeitsstands.")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.lookups.gameBox", "Kennung:            advances\nArt:                Aus dem Spiel\nOrdner:             in_game/common/advances\nTiefe:              1\nTag aus Dateiname:  ^country_([A-Za-z]{2,5})\\.txt$\nTag im Block:       has_or_had_tag, tag")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.lookups.json", "„JSON-Datei“ liest eine Datei, die das Paket als Asset nennt. Der Elemente-Pfad führt zu den Einträgen, name[] steigt in jedes Element einer Liste. Die Zuordnung nennt je Eintragsfeld die Eigenschaft; ../x liest x aus dem übergeordneten Element:")),
        new GuideBlock(GuideBlockKind.Example, T("generatorhelp.lookups.jsonBox", "{ \"cities\": [ { \"tag\": \"HAM\", \"arms\": [ { \"id\": \"ham_ship\", \"title\": \"Hansekogge\" } ] } ] }\n\nElemente-Pfad:  cities[].arms[]\nZuordnung:      key = id, name = title, tag = ../tag")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.lookups.preview", "„Vorschau“ liest die Quelle wie der Generator und zeigt die Anzahl und die ersten 50 Einträge. Kommt nichts, steht der Grund da: Spielordner fehlt, Asset-Datei fehlt, Ordner ohne .txt-Dateien oder ein Pfad, der nichts trifft. Ordner bleiben im Spielordner; ein Ordner mit .. wird abgelehnt.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.lookups.field", "In der Maske eines Text-Felds schaltet „Aus Datenbank nachschlagen“ den Knopf „Aus Datenbank“ im Generator ein. Wähle die Quellen und die Felder derselben Ebene, die Name und Beschreibung bekommen; mindestens eins. Benennst du eine Quelle oder ein Feld um, ziehen die Verweise mit.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.candidates.heading", "Modifier ohne Idee"), "generatorhelp.candidates"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.candidates.text", "Der Knopf „Modifier ohne Idee…“ erscheint bei Paketen mit dem Abschnitt candidates (z. B. IV2 dynamische Ideen). Er listet die Modifier des Spiels, die noch keine Idee der Mod benutzt.\n• Benutzt: Ein Modifier zählt als benutzt, wenn er in einem der im Paket genannten Blöcke der Mod steht. Auskommentierte Zeilen zählen nicht. Bei IV2 sind das die Blöcke national_idea_modifier_<Kategorie>_<Nummer> in den vier Dateien 01_IV2_dynamic_national_ideas_<Kategorie>.txt; alte Länderideen und Ideengruppen zählen nicht.\n• neu: Die Marke ✱ zeigt Modifier, die der jüngste Import der Script-Datenbank neu gebracht hat. „Nur neue“ zeigt nur diese.\n• Gruppen: Das Paket sortiert die Modifier in Gruppen (links). Was in keine passt, steht unter „Allgemein“; „Alle“ zeigt alles. Die Suche gilt immer für alle Gruppen und findet auch Modifier in ausgeblendeten Gruppen.\n• Ausblenden: Das Häkchen „ausblenden“ blendet eine Gruppe aus, bei IV2 z. B. die Güter-Gruppen. Sie bleibt links stehen, grau und mit ihren Zahlen, damit ein neuer Modifier darin nicht unbemerkt bleibt. Dazu kommt die eigene Regex über der Liste, die Modifier nach Schlüssel ausblendet. Wählst du links eine ausgeblendete Gruppe, zeigt die Liste ihre Modifier trotzdem. „Ausgeblendete zeigen“ holt alles zurück, auch die Modifier „nicht als Idee“ und die von der Regex getroffenen.\n• Nicht als Idee: Merkt gewählte Modifier vor, die keine Idee werden sollen. Sie sind dann in jeder Ansicht ausgeblendet, auch in ihrer Gruppe; mit „Ausgeblendete zeigen“ erscheinen sie grau, und „Wieder anzeigen“ nimmt die Markierung zurück.\n• Arbeitsstand: Steht ein Modifier schon in einem Arbeitsstand des Pakets, nennt die Spalte „Arbeitsstand“ dessen Schlüssel.\n• Anlegen…: Legt für jeden gewählten Modifier einen Arbeitsstand an. Steht einer schon in einem Arbeitsstand, fragt PMT vorher nach. Die gefragten Angaben (bei IV2 Kategorie und Unter-Reiter) fragt PMT einmal, die Nummer vergibt es fortlaufend. Der Name ist der offizielle Name des Modifiers in jeder Sprache. Der Modifier steht auf allen Stufen, ein Ja/Nein-Modifier auf einer Stufe mit yes.\nDie Werte bleiben absichtlich leer: Du trägst sie selbst ein. „Erzeugen“ verweigert leere Werte, bis alle ausgefüllt sind.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.check.heading", "Prüfen und Testen"), "generatorhelp.check"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.check.check", "„Prüfen“ lädt den aktuellen Stand probeweise mit dem echten Lader und lässt Scriban alle Vorlagen, Pfade, Blöcke und Bedingungen lesen. Ist alles lesbar, erzeugt es jede Vorlage einmal mit Beispielwerten und findet so unbekannte Namen. Eine .yml-Ausgabe, die nicht von der Art „Lokalisierung“ ist, wird gemeldet. Der Lader meldet nur seinen ersten Fehler; nach der Korrektur erneut prüfen. Ein Klick auf einen Vorlagenfehler springt zur Zeile.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.check.save", "Das erste Speichern schreibt package.json neu formatiert: Inhalt gleich, Layout anders. Kommentare in package.json gehen dabei verloren; PMT warnt vorher.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.check.test", "„Im Generator testen“ speichert und öffnet das Generator-Fenster auf diesem Paket. Lege dort einen Arbeitsstand an, wähle das Ziel „Ausgabeordner“ und prüfe die Vorschau, bevor du in die Mod schreibst.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.archive.heading", "Export und Import"), "generatorhelp.archive"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.archive.export", "„Exportieren“ schreibt das Paket als .pmtgen-Datei: package.json, functions.sbn und die Vorlagen immer, Arbeitsstände und Assets aus Mods auf Wunsch. Assets aus dem Spiel bleiben immer draußen.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.archive.import", "„Importieren“ zeigt erst, was in der Datei steckt, und legt das Paket im Ordner seines Spiels an. Gehört die Kennung einem mitgelieferten Paket, braucht der Import eine neue Kennung. Gibt es schon ein eigenes Paket mit der Kennung, wählst du Ersetzen (gleichnamige Arbeitsstände nach Rückfrage) oder eine neue Kennung.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.archive.safety", "Sicherheit:\n• PMT liest nur erlaubte Einträge: package.json, functions.sbn, Vorlagen, Arbeitsstände und als Mod-Asset angegebene Dateien.\n• Einträge mit .., Laufwerk oder absolutem Pfad werden übersprungen und genannt.\n• Größen zählt PMT beim Lesen: Paketdateien höchstens 5 MB je Datei und 50 MB zusammen, Assets höchstens 1 GB je Datei und 2 GB zusammen.\n• Ausgeführt wird beim Import nichts. Die Vorlagen eines fremden Pakets können beim Erzeugen nur in die Mod oder den Ausgabeordner schreiben; prüfe trotzdem die Vorschau.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.ai.heading", "Mit KI erstellen"), "generatorhelp.ai"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.intro", "Ein Paket von Hand zu bauen ist viel Arbeit. „Mit KI erstellen“ (im Paket-Editor und im Generator-Fenster) gibt diese Arbeit an eine KI deiner Wahl ab: PMT stellt den Auftrag zusammen, die KI schreibt package.json und die Vorlagen, PMT übernimmt die Antwort und prüft sie.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.steps", "In fünf Schritten:\n1. Mod wählen und die Dateien eines fertigen Satzes anhaken, z. B. alles zu einem Tag, auch Lokalisierung und Einträge in gemeinsamen Dateien.\n2. Beschreiben, was das Formular abfragen soll.\n3. „Als Text kopieren“ und in eine Chat-KI einfügen, oder „Als Ordner speichern“ für eine KI mit Dateizugriff.\n4. Die Antwort unter „Ergebnis“ einfügen und „Übernehmen“ drücken (oder den Ordner der KI importieren).\n5. Meldet „Prüfen“ Fehler, „Fehler für die KI kopieren“ und der KI zurückgeben, bis alles passt. Dann „Im Generator testen“.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.snippets", "Große Dateien überfordern kostenlose Chat-KIs schnell. Dann im Reiter „Codeblöcke“ nur die passenden Stellen einfügen, je mit dem Pfad der Datei in der Mod („Aus Mod wählen“) und dem Umfang: „Ganze Datei“ oder „Ausschnitt“, wenn der Rest der Datei stehen bleiben soll. Dateien und Codeblöcke lassen sich mischen. Die Blöcke bleiben, solange das Fenster offen ist; „Als Datei speichern“ hebt den ganzen Auftrag auf.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.snippetTools", "Jeder Block kann eine „Erläuterung“ bekommen: Sie sagt der KI, was an genau diesem Block wichtig ist, z. B. „wiederholt sich je Idee“. „Aus Mod-Datei übernehmen“ und „Aus Spieldatei übernehmen“ öffnen eine Datei; die markierten Zeilen werden mit Pfad zum neuen Block. Blöcke aus dem Spiel sind als „Datei des Spiels“ markiert und dienen der KI als Vorbild. Ein Klick auf die Kopfzeile klappt einen Block zu; „Alle zuklappen“ hält lange Listen übersichtlich.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.tips","Tipps:\n• Ein vollständiges Vorbild wählen: Fehlt eine Datei, fehlt sie im Paket.\n• Klein anfangen, z. B. nur Modifikatoren und Lokalisierung, und dann erweitern.\n• Mit „Offenes Paket mitgeben“ ändert die KI ein vorhandenes Paket; Kennung und Markierungs-Kennung bleiben.\n• Die Anleitung für die KI liegt im Programmordner unter ai-guide/generator-packages (auch als Claude-Skill nutzbar).")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.ai.cli", "Für KIs mit Dateizugriff liegt pmt-generator.exe im Programmordner:\n• check <Paketordner>: lädt und prüft das Paket wie „Prüfen“.\n• probe <Paketordner> <Modordner> [<Schlüssel>]: Probelauf des Einlesens.\n• roundtrip <Paketordner> <Modordner> <Schlüssel>: liest einen Satz aus der Mod, erzeugt ihn neu und vergleicht jede Datei. Stimmt alles überein, ist das Paket richtig.\nDer Befehl schreibt nie in Mod oder Paket.")),

        new GuideBlock(GuideBlockKind.Heading, T("generatorhelp.generator.heading", "Im Generator-Fenster"), "generatorhelp.generator"),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.generator.states", "Links wählst du Paket und Arbeitsstand, rechts füllst du das Formular. „Vorschau“ zeigt jede Datei vorher und nachher; mit U nimmst du markierte Änderungen zurück. „Erzeugen“ schreibt alles als einen Rückgängig-Schritt. „Paket bearbeiten“ öffnet das Paket im Paket-Editor.")),
        new GuideBlock(GuideBlockKind.Paragraph, T("generatorhelp.generator.tools", "Hat das Paket einen Einleser, liest „Aus Mod einlesen“ einen vorhandenen Satz aus der Mod, „Tags aus Mod übernehmen“ legt Arbeitsstände für alle Schlüssel an und „Mod prüfen“ vergleicht Mod und Arbeitsstände. „Aus Datenbank“ übernimmt Namen und Beschreibungen aus Nachschlage-Quellen, „+ Modifier“ sucht Modifikatoren und „Wappen wählen“ zeigt die Bilder einer Bibliothek.")),
    };

    /// <summary>Höchstens ein Anleitungsfenster; ein offenes wird nach vorn geholt. Mit <paramref name="section"/> springt es zum Kapitel.</summary>
    public static void Show(Window owner, string? section)
    {
        if (_open is null)
        {
            _open = new GeneratorPackageHelpWindow { Owner = owner };
            _open.Closed += (_, _) => _open = null;
            _open.Show();
        }
        else
        {
            _open.Activate();
        }

        if (section is not null)
        {
            _open.ShowSection(section);
        }
    }

    // Nur UiText.Get, kein Format: die Texte enthalten geschweifte Klammern ({{ tag }}).
    private static string T(string key, string german) => UiText.Get(key, german);
}
